import{_ as s,a0 as a,w as b,s as d,ao as r,I as p,a1 as u,A as n,x as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"Ubuntu每日小技巧-Ubuntu One关闭后如何切换到Dropbox或Box云服务 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu每日小技巧-Ubuntu One关闭后如何切换到Dropbox或Box云服务 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu每日小技巧-Ubuntu One关闭后如何切换到Dropbox或Box云服务 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu每日小技巧-Ubuntu One关闭后如何切换到Dropbox或Box云服务 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/Daily Ubuntu Tips--Ubuntu One Shuts Down, Switch To Dropbox Or Box Cloud Services","title":"Ubuntu每日小技巧-Ubuntu One关闭后如何切换到Dropbox或Box云服务","tag":"201405","desc":""},"relativePath":"201405/Daily Ubuntu Tips--Ubuntu One Shuts Down, Switch To Dropbox Or Box Cloud Services.md","filePath":"[post].md"}'),i={name:"201405/Daily Ubuntu Tips--Ubuntu One Shuts Down, Switch To Dropbox Or Box Cloud Services.md"};function l(x,t,T,f,w,D){const e=a("Link");return b(),d("div",null,[t[12]||(t[12]=r('<h1 id="ubuntu每日小技巧-ubuntu-one关闭后如何切换到dropbox或box云服务" tabindex="-1">Ubuntu每日小技巧-Ubuntu One关闭后如何切换到Dropbox或Box云服务 <a class="header-anchor" href="#ubuntu每日小技巧-ubuntu-one关闭后如何切换到dropbox或box云服务" aria-label="Permalink to “Ubuntu每日小技巧-Ubuntu One关闭后如何切换到Dropbox或Box云服务”">​</a></h1><p>Canonical公司决定关闭Ubuntu One的云服务，你可能正在寻找备份你主机的其他服务器，尽管现在有很多云服务的提供商，但是大服务商中仅有小部分支持包括Ubuntu在内的linux。</p><p>Dropbox全面支持Ubuntu，它有一个很好的整合了ubuntu桌面系统和其他通知栏的客户端。Box，官方的Box.net也可以通过WebDav协议支持linux。</p><p>这里有一段来自Canonical公司关于Ubuntu One的摘录：</p><blockquote><p>从4月2日开始，就不能访问Ubuntu One中的存储或音乐了。Ubuntu One服务也不会再包含在Ubuntu 14.04 LTS中，而Ubuntu One的应用也将从Ubuntu、Google和Apple的应用商店移除。</p></blockquote><p>也就是说我们在ubuntu中失去了这项有用的服务。另一方面，把你的数据移动到一个更稳定、更好信誉的网盘提供商是一个比较好的选择。</p><p>这里简要的说明一下怎样在ubuntu中运行DropBox或者Box云服务。</p><p>###在ubuntu中安装DropBox云盘</p><p>关于这个话题我们已经写了很多，为了在ubuntu中安装DropBox云盘，你需要按照以下步骤去做，这里提供了一个在ubuntu中一步步安装和使用DropBox的步骤。</p><p>查看完整步骤，点这里，或者下面的链接：</p>',10)),p("p",null,[u(e,{href:"http://www.liberiangeek.net/2013/03/how-to-install-dropbox-in-ubuntu-13-04-raring-ringtail/"},{default:n(()=>[...t[0]||(t[0]=[o("http://www.liberiangeek.net/2013/03/how-to-install-dropbox-in-ubuntu-13-04-raring-ringtail/",-1)])]),_:1})]),t[13]||(t[13]=r(`<p>###在Ubuntu中使用Box网盘</p><p>自从Box不再提供给包括ubuntu在内的linux一个全功能客户端，你就必须使用WebDav协议来访问和存储你账户的东西。</p><p>按Ctrl – Alt – T来打开终端，终端被打开后，执行下面的命令来安装包：</p><pre><code>sudo apt-get install davfs2
</code></pre><p>接下来，执行下面的命令来配置davfs2，选择Yes来允许没有权限的用户来挂载WebDav资源。</p><pre><code>sudo dpkg-reconfigure davfs2
</code></pre><p>接下来通过执行下面的命令把davfs2目录复制到你的home目录：</p><pre><code>sudo cp -r /etc/davfs2/ $HOME/.davfs2
</code></pre><p>然后执行下面命令获取文件夹的所有权：</p><pre><code>sudo chown -R username $HOME/.davfs2/
</code></pre><p>用你的用户名代替username</p><p>接下来打开密码文件输入你的登录凭证：</p><pre><code>gedit ~/.davfs2/secrets
</code></pre><p>然后键入你的用户名（email地址）和密码，在文件末尾添加下面的行并保存。</p><pre><code>https://dav.box.com/dav richard@liberiangeek.net  &lt;box_password&gt;
</code></pre><p>用你的账户信息替换上面的email地址和password。</p><p>接下来用下面的命令添加你的账户到davfs2组中：</p><pre><code>sudo adduser &lt;username&gt; davfs2
</code></pre><p>然后用sudo gedit /etc/fstab 打开/etc/fstab在后面添加下面一行并保存：</p><pre><code>https://dav.box.com/dav/ /home/&lt;username&gt;/box  davfs _netdev,rw,user 0 0 
</code></pre><p>最后创建一个挂载点并挂载Box</p><pre><code>mkdir ~/box
</code></pre><p>重启你的电脑，Box能开机自动挂载了，</p><p>享受下吧！</p><hr>`,25)),p("p",null,[t[2]||(t[2]=o("via: ",-1)),u(e,{href:"http://www.liberiangeek.net/2014/04/daily-ubuntu-tips-ubuntu-one-shuts-down-switch-to-dropbox-or-box-cloud-services/"},{default:n(()=>[...t[1]||(t[1]=[o("http://www.liberiangeek.net/2014/04/daily-ubuntu-tips-ubuntu-one-shuts-down-switch-to-dropbox-or-box-cloud-services/",-1)])]),_:1})]),p("p",null,[t[5]||(t[5]=o("译者：",-1)),u(e,{href:"https://github.com/yujianxuechuan"},{default:n(()=>[...t[3]||(t[3]=[o("yujianxuechuan ",-1)])]),_:1}),t[6]||(t[6]=o(" 校对：",-1)),u(e,{href:"https://github.com/%E6%A0%A1wxy"},{default:n(()=>[...t[4]||(t[4]=[o("wxy",-1)])]),_:1})]),p("p",null,[t[9]||(t[9]=o("本文由 ",-1)),u(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[7]||(t[7]=[o("LCTT",-1)])]),_:1}),t[10]||(t[10]=o(" 原创翻译，",-1)),u(e,{href:"http://linux.cn/"},{default:n(()=>[...t[8]||(t[8]=[o("Linux中国",-1)])]),_:1}),t[11]||(t[11]=o(" 荣誉推出",-1))])])}const v=s(i,[["render",l]]);export{_ as __pageData,v as default};
